import{c as s,U as i,j as n,g as e,o as r,a6 as o,n as l}from"./chunks/framework.h4W4t1IS.js";const b=JSON.parse('{"title":"JDK 25 LTS","description":"","frontmatter":{"title":"JDK 25 LTS","status":"ready","tags":["env","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"env/jdk.md","filePath":"env/jdk.md"}'),d={name:"env/jdk.md"},p={id:"frontmatter-title",tabindex:"-1"};function u(a,t,c,h,g,m){return i(),n("div",null,[e("h1",p,[r(o(a.$frontmatter.title)+" ",1),t[0]||(t[0]=e("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),t[1]||(t[1]=l(`<p>Le JDK (Java Development Kit) est l&#39;ensemble d&#39;outils nécessaires pour compiler et exécuter des programmes Java. Nous utiliserons la version <strong>25 LTS</strong> (Long-Term Support), la version stable maintenue à long terme.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Différencier le JDK, le JRE et la JVM</li><li>Installer le JDK 25 sur ton poste</li><li>Confirmer que l&#39;installation est fonctionnelle</li><li>Justifier le choix d&#39;une version LTS</li></ul></div><h2 id="jdk-jre-et-jvm" tabindex="-1">JDK, JRE et JVM <a class="header-anchor" href="#jdk-jre-et-jvm" aria-label="Permalink to &quot;JDK, JRE et JVM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composant</th><th>Rôle</th></tr></thead><tbody><tr><td><strong>JVM</strong> (Java Virtual Machine)</td><td>Exécute le bytecode Java</td></tr><tr><td><strong>JRE</strong> (Java Runtime Environment)</td><td>JVM + bibliothèques standards (pour exécuter)</td></tr><tr><td><strong>JDK</strong> (Java Development Kit)</td><td>JRE + compilateur + outils de développement (pour développer)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">En résumé</p><p>Pour <strong>développer</strong> en Java, tu as besoin du JDK. Pour <strong>exécuter</strong> seulement, le JRE suffit.</p></div><div class="info custom-block"><p class="custom-block-title">Autres langages supportés par la JVM</p><ul><li>Kotlin : développement mobile pour Android</li><li>Clojure: langage fonctionnel dérivé de LISP</li><li>Scala: Langage multi-paradigme fortement typé (oo et fonctionnel)</li></ul><p><a href="https://en.wikipedia.org/wiki/List_of_JVM_languages" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/List_of_JVM_languages</a></p></div><h2 id="pourquoi-la-version-25-lts" tabindex="-1">Pourquoi la version 25 LTS? <a class="header-anchor" href="#pourquoi-la-version-25-lts" aria-label="Permalink to &quot;Pourquoi la version 25 LTS?&quot;">​</a></h2><p>Java publie deux versions par année. Les versions <strong>LTS</strong> (Long-Term Support) bénéficient de corrections de sécurité pendant plusieurs années. La version 25 est la LTS la plus récente et inclut toutes les fonctionnalités importantes pour ce cours :</p><ul><li><strong><a href="/420-w30-sf-po2/lexique.html#record" class="lexicon-link" title="Type de classe Java (16+) conçu pour les données immuables; génère automatiquement constructeur, accesseurs (sans préfixe get), equals, hashCode et toString. Ne peut pas hériter.">Records</a></strong> - classes immuables déclaratives</li><li><strong>Sealed classes</strong> - hiérarchies fermées</li><li><strong>Pattern matching</strong> - <code>instanceof</code> simplifié et switch expressions</li><li><strong>Text blocks</strong> - chaînes multilignes</li><li><strong>Virtual threads</strong> (Project Loom) - concurrence légère</li></ul><h3 id="duree-du-support-en-fonction-des-types-de-versions" tabindex="-1">Durée du support en fonction des types de versions <a class="header-anchor" href="#duree-du-support-en-fonction-des-types-de-versions" aria-label="Permalink to &quot;Durée du support en fonction des types de versions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Version</th><th>Date d&#39;adoption</th><th>Support</th><th>Support étendu</th><th>Support continu</th></tr></thead><tbody><tr><td>8 (LTS**)</td><td>03-2014</td><td>03-2022</td><td>12-2030</td><td>Indéfini</td></tr><tr><td>11 (LTS)</td><td>09-2018</td><td>09-2023</td><td>01-2032</td><td>Indéfini</td></tr><tr><td>17 (LTS)</td><td>08-2021</td><td>09-2026</td><td>09-2029</td><td>Indéfini</td></tr><tr><td>21 (LTS)</td><td>09-2023</td><td>09-2028</td><td>09-2031</td><td>Indéfini</td></tr><tr><td><strong>25 (LTS)</strong></td><td><strong>09-2025</strong></td><td><strong>09-2030</strong></td><td><strong>09-2033</strong></td><td><strong>Indéfini</strong></td></tr><tr><td>26</td><td>03-2026</td><td>09-2026</td><td>--</td><td>Indéfini</td></tr><tr><td>27</td><td>09-2026</td><td>03-2027</td><td>--</td><td>Indéfini</td></tr></tbody></table><p>** Versions LTS - 9 à 15 ans de support</p><h2 id="telechargement-et-installation" tabindex="-1">Téléchargement et installation <a class="header-anchor" href="#telechargement-et-installation" aria-label="Permalink to &quot;Téléchargement et installation&quot;">​</a></h2><ol><li>Aller sur <a href="https://adoptium.net/" target="_blank" rel="noreferrer">adoptium.net</a> (distribution Eclipse Temurin, version open-source recommandée)</li><li>Sélectionner <strong>Temurin 25 (LTS)</strong> - vérifier que « LTS » est indiqué</li><li>Choisir le système d&#39;exploitation et l&#39;architecture (<code>Windows, X64</code>)</li><li>Télécharger et exécuter l&#39;installateur</li></ol><h2 id="verification-de-l-installation" tabindex="-1">Vérification de l&#39;installation <a class="header-anchor" href="#verification-de-l-installation" aria-label="Permalink to &quot;Vérification de l&#39;installation&quot;">​</a></h2><p>Dans un terminal :</p><h3 id="jdk" tabindex="-1">JDK <a class="header-anchor" href="#jdk" aria-label="Permalink to &quot;JDK&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>Résultat attendu (les numéros mineurs peuvent varier) :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openjdk version &quot;25.0.1&quot; 2025-xx-xx LTS</span></span>
<span class="line"><span>OpenJDK Runtime Environment Temurin-25.0.x+8 (build 25.0.1+8-LTS)</span></span>
<span class="line"><span>OpenJDK 64-Bit Server VM Temurin-25.0.x+8 (build 25.0.1+8-LTS, mixed mode, sharing)</span></span></code></pre></div><h3 id="javac-compilateur" tabindex="-1">JAVAC (compilateur) <a class="header-anchor" href="#javac-compilateur" aria-label="Permalink to &quot;JAVAC (compilateur)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">javac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>Résultat attendu :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javac 25.0.x</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Variable JAVA_HOME</p><p>Sur certains systèmes, la variable d&#39;environnement <code>JAVA_HOME</code> doit pointer vers le répertoire d&#39;installation du JDK. IntelliJ IDEA gère cela automatiquement pour les projets qu&#39;il ouvre.</p></div>`,26))])}const f=s(d,[["render",u]]);export{b as __pageData,f as default};
